// Merge hero-specific enrichment overlay (differentiated support builds,
// hero-specific combos/playstyle/skillBuild/counters/goodAgainst/difficulty/patchTier)
// over the base builds at module load. Consumers (heroBuilds[id] / getBuild) see enriched data.
const _merged: Record<string, HeroBuild> = {};
for (const id of Object.keys(_baseBuilds)) {
  const base = _baseBuilds[id];
  const en = enrichments[id];
  _merged[id] = en
    ? {
        heroId: base.heroId,
        core: base.core,
        support: en.support ?? base.support,
        combos: en.combos,
        playstyle: en.playstyle,
        skillBuild: en.skillBuild,
        counters: en.counters,
        goodAgainst: en.goodAgainst,
        difficulty: en.difficulty,
        patchTier: en.patchTier,
      }
    : base;
}
export const heroBuilds: Record<string, HeroBuild> = _merged;

export const getBuild = (heroId: string): HeroBuild | undefined => heroBuilds[heroId];